def diameterOfBinaryTree(root):
    def depth(n):
        d, level = 0, ([n] if n else [])
        while level:
            d += 1
            level = [c for x in level for c in (x.left, x.right) if c]
        return d
    best = 0
    stack = [root] if root else []
    while stack:
        n = stack.pop()
        best = max(best, depth(n.left) + depth(n.right))
        if n.left:
            stack.append(n.left)
        if n.right:
            stack.append(n.right)
    return best

